def name_operands(region,function_address,operation):
    if region=='Action' and function_address in FUNCTIONS:
        from ActionClipProductsData import RECORDS
        for name,address in RECORDS:
            for offset,field in ((0,'LowWord'),(2,'HighWord')):
                operation=operation.replace('(#'+format(address+offset,'04X')+')','(@ActionClipProductsData.'+name+'.'+field+')')
        for address,expression in ((0xCF0B,'FirstPoint+FRenderProjectedPoint.Second'),(0xCF0D,'FirstPoint+FRenderProjectedPoint.First'),(0xCF1B,'SecondPoint+FRenderProjectedPoint.Second'),(0xCF1D,'SecondPoint+FRenderProjectedPoint.First')):
            operation=operation.replace('(#'+format(address,'04X')+')','(@ActionClipProductsState.'+expression+')')
    for point in ('FirstPoint','SecondPoint'):
        operation=operation.replace('@ActionClipProductsState.'+point+'+FRenderProjectedPoint.','@ActionClipPoints.'+point+'.')
    return operation
